# QA-T1-05: e-mail único sem diferenciar maiúsculas. Antes de criar a
# constraint, normaliza (strip + lower) os e-mails já gravados. Se existirem
# duplicados por caixa a migração falha de propósito (resolver manualmente).

import django.db.models.functions.text
from django.db import migrations, models


def normalize_emails(apps, schema_editor):
    User = apps.get_model("accounts", "User")
    for user in User.objects.only("pk", "email").iterator():
        normalized = (user.email or "").strip().lower()
        if normalized != user.email:
            User.objects.filter(pk=user.pk).update(email=normalized)


